<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main">
    <section class="card" aria-labelledby="support-title">
      <p class="eyebrow">Support</p>
      <h1 id="support-title">Contact our team</h1>
      <p class="lede">Send us a message and we’ll get back to you as soon as possible.</p>

      <form id="contact-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          >
          <p class="field-error" id="full-name-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="emailAddress"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-address-error"
          >
          <p class="field-error" id="email-address-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phoneNumber"
            type="tel"
            autocomplete="tel"
            aria-describedby="phone-number-help phone-number-error"
          >
          <p class="field-note" id="phone-number-help">Expected format: +1 555 123 4567 or another common international format.</p>
          <p class="field-error" id="phone-number-error" hidden></p>
        </div>

        <button type="submit">Submit</button>
      </form>
    </section>
  </main>

