  <script>
    const form = document.getElementById('contact-form');
    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        required: true,
        label: 'Full name'
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        required: true,
        label: 'Email address'
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        required: false,
        label: 'Phone number'
      }
    ];

    const phonePattern = /^(?=.*\d)[+()0-9\s.-]{7,}$/;

    function setError(field, message) {
      field.input.setAttribute('aria-invalid', 'true');
      field.error.textContent = message;
      field.error.hidden = false;
    }

    function clearError(field) {
      field.input.removeAttribute('aria-invalid');
      field.error.textContent = '';
      field.error.hidden = true;
    }

    function validateField(field) {
      const { input, label, required } = field;
      const value = input.value.trim();

      if (required && value === '') {
        setError(field, `${label} is required.`);
        return false;
      }

      if (input.type === 'email' && input.validity.typeMismatch) {
        setError(field, 'Enter a valid email address.');
        return false;
      }

      if (input.id === 'phone-number' && value && !phonePattern.test(value)) {
        setError(field, 'Enter a phone number in a common international format.');
        return false;
      }

      clearError(field);
      return true;
    }

    fields.forEach(({ input }) => {
      input.addEventListener('input', () => {
        if (input.getAttribute('aria-invalid') === 'true') {
          const field = fields.find((item) => item.input === input);
          validateField(field);
        }
      });
      input.addEventListener('blur', () => {
        const field = fields.find((item) => item.input === input);
        validateField(field);
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const invalidField = fields.find((field) => !validateField(field));

      if (invalidField) {
        invalidField.input.focus();
        return;
      }

      form.reset();
      fields.forEach(clearError);
    });
  </script>
